WITH filtered AS (SELECT id, order_id, quantity, unit_price - quantity AS line_total FROM order_items WHERE product_id IS NOT NULL AND order_id IN (5, 8, 37)), with_windows AS (SELECT *, FIRST_VALUE(quantity) IGNORE NULLS OVER w_grp AS first_known_quantity, LAST_VALUE(quantity, TRUE) OVER w_ordered AS last_known_quantity FROM filtered WHERE order_id IN (10, 32) WINDOW w_grp AS (PARTITION BY order_id ORDER BY line_total, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_ordered AS (ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), remaining_keys AS (SELECT id, order_id FROM with_windows EXCEPT ALL SELECT id, order_id FROM order_items WHERE unit_price BETWEEN 150 AND 340), reconciled AS (SELECT s.* FROM with_windows s INNER JOIN remaining_keys k ON s.id = k.id AND s.order_id = k.order_id), enriched AS (SELECT src.*, d.status FROM reconciled src INNER JOIN orders d ON src.order_id = d.id), metrics AS (SELECT id, order_id, quantity, line_total, last_known_quantity, SUM(last_known_quantity) OVER (PARTITION BY status, order_id) AS status_sum_last_known_quantity, CUME_DIST() OVER (ORDER BY first_known_quantity NULLS LAST) AS first_known_quantity_cume_dist, STDDEV_SAMP(quantity) OVER w_hist AS order_id_stddev_samp_quantity, STDDEV_SAMP(last_known_quantity) OVER w_hist AS order_id_stddev_samp_last_known_quantity FROM enriched WINDOW w_hist AS (PARTITION BY order_id)), enriched_order_items AS (SELECT a.id, a.order_id, a.last_known_quantity, d.amount, d.channel FROM metrics a INNER JOIN orders d ON a.order_id = d.id), with_dims AS (SELECT src.id, src.order_id, src.last_known_quantity, p.channel AS order_channel FROM enriched_order_items src INNER JOIN orders p ON src.order_id = p.id) SELECT CASE WHEN last_known_quantity >= 8 THEN 'HIGH' ELSE 'LOW' END AS last_known_quantity_tier, order_channel, COUNT_IF(order_channel = 'mobile') AS mobile_events, COUNT(*) FILTER (WHERE order_channel = 'partner') AS partner_rows, COUNT(DISTINCT order_channel) AS distinct_order_channels, ROUND(SUM(last_known_quantity) / NULLIF(COUNT(CASE WHEN order_channel = 'mobile' THEN 1 END), 0), 2) AS last_known_quantity_per_mobile, SORT_ARRAY(COLLECT_SET(order_channel)) AS order_channel_list, COUNT(DISTINCT id) AS distinct_ids FROM with_dims GROUP BY CASE WHEN last_known_quantity >= 8 THEN 'HIGH' ELSE 'LOW' END, order_channel HAVING partner_rows > 1 ORDER BY distinct_order_channels
